import zipfile

# Peek inside the scogs zip files to understand the output structure
for zname in ['scogs_animals.zip', 'scogs_fungi.zip']:
    with zipfile.ZipFile(zname) as z:
        names = z.namelist()
        print(f"\n=== {zname} ({len(names)} files) ===")
        for n in names[:30]:
            print(n)
        if len(names) > 30:
            print(f"... and {len(names)-30} more")
